import{_ as e,o as i,c as s,ag as a}from"./chunks/framework.DNmTgtHf.js";const y=JSON.parse('{"title":"Lists in Java — types, choices, and the Array trap","description":"","frontmatter":{},"headers":[],"relativePath":"java/foundations/collections/lists/Lists.md","filePath":"java/foundations/collections/lists/Lists.md"}'),o={name:"java/foundations/collections/lists/Lists.md"};function r(d,t,n,c,l,h){return i(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="lists-in-java-—-types-choices-and-the-array-trap" tabindex="-1">Lists in Java — types, choices, and the Array trap <a class="header-anchor" href="#lists-in-java-—-types-choices-and-the-array-trap" aria-label="Permalink to &quot;Lists in Java — types, choices, and the Array trap&quot;">​</a></h1><p>The first family of collections to know. Picking the right list type matters: builders accumulate elements, factories return read-only views, and registries occasionally hand back lists. Companion demos sit alongside this doc in <code>basics/</code>, <code>immutability/</code>, <code>performance/</code>, and <code>concurrent/</code>.</p><hr><h2 id="list-options" tabindex="-1">List options <a class="header-anchor" href="#list-options" aria-label="Permalink to &quot;List options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Backed by</th><th>Allows null</th><th>Thread-safe</th><th>When to use</th></tr></thead><tbody><tr><td><code>ArrayList</code></td><td>Dynamic array</td><td>Yes</td><td>No</td><td>Default list. Fast random access (<code>get(i)</code>), fast add at end, slow insert/delete in the middle.</td></tr><tr><td><code>LinkedList</code></td><td>Doubly-linked list</td><td>Yes</td><td>No</td><td>Fast insert/delete at both ends. Slow random access. Rarely the right choice in modern Java.</td></tr><tr><td><code>List.of(...)</code></td><td>Immutable array</td><td>No</td><td>Yes (immutable)</td><td>Read-only lists; cannot add, remove, or set elements. Use when the list is truly fixed.</td></tr><tr><td><code>Collections.unmodifiableList(...)</code></td><td>Wraps any list</td><td>Depends</td><td>Depends</td><td>Makes an existing list unmodifiable from the outside, but the backing list can still change.</td></tr><tr><td><code>Arrays.asList(...)</code></td><td>Fixed-size array</td><td>Yes</td><td>No</td><td>Fixed-size but mutable — <code>set</code> works, <code>add</code>/<code>remove</code> throw. A common surprise.</td></tr><tr><td><code>CopyOnWriteArrayList</code></td><td>Array, copied on write</td><td>Yes</td><td>Yes</td><td>Thread-safe reads; every write copies the entire backing array. Use when reads vastly outnumber writes (listener lists, config caches).</td></tr></tbody></table><ul><li>[ ] Understand <code>ArrayList</code> vs <code>LinkedList</code> Big-O comparison — why <code>ArrayList</code> wins almost everywhere.</li><li>[ ] Understand <code>List.of()</code> vs <code>Collections.unmodifiableList()</code> — the subtle difference is that the backing list of <code>unmodifiableList</code> can still be mutated externally.</li><li>[ ] Understand <code>Arrays.asList()</code> — the fixed-size trap (<code>add</code>/<code>remove</code> throw <code>UnsupportedOperationException</code> even though it looks mutable).</li><li>[ ] Understand <code>CopyOnWriteArrayList</code> — every write copies the backing array; iterators see a snapshot at iterator-creation time. Concurrent reads are lock-free.</li></ul><hr><h2 id="array-vs-arraylist" tabindex="-1">Array vs. ArrayList <a class="header-anchor" href="#array-vs-arraylist" aria-label="Permalink to &quot;Array vs. ArrayList&quot;">​</a></h2><ul><li><strong>Array (<code>int[]</code>, <code>String[]</code>):</strong> fixed size, holds primitives natively (no boxing), no generics. Use when size is known upfront and avoiding boxing overhead matters.</li><li><strong><code>ArrayList&lt;T&gt;</code>:</strong> dynamic size, holds objects only (primitives are boxed). Use when size can grow or shrink.</li><li><strong>Key trap — covariance:</strong> arrays are covariant — <code>String[]</code> is an <code>Object[]</code>. Generics are invariant — <code>List&lt;String&gt;</code> is <strong>not</strong> a <code>List&lt;Object&gt;</code>. Storing the wrong type into an array fails at runtime with <code>ArrayStoreException</code>; with generics it&#39;s caught at compile time.</li></ul><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Object</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[] arr </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">arr[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 42</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;                      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// compiles, ArrayStoreException at runtime</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">List&lt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; list </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ArrayList&lt;&gt;();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">List&lt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Object</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; objList </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> list;      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// won&#39;t compile — generics are invariant</span></span></code></pre></div><p>Compile-time errors beat runtime errors — the strongest single argument for <code>List&lt;T&gt;</code> over arrays in modern Java code.</p><hr><h2 id="demo-code-in-this-folder" tabindex="-1">Demo code in this folder <a class="header-anchor" href="#demo-code-in-this-folder" aria-label="Permalink to &quot;Demo code in this folder&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Demo</th><th>Shows</th></tr></thead><tbody><tr><td><code>basics/ArrayListBasicsRun</code></td><td>Basic <code>ArrayList</code> usage — declare, add, print</td></tr><tr><td><code>basics/LinkedListBasicsRun</code></td><td>Basic <code>LinkedList</code> usage</td></tr><tr><td><code>immutability/ListOfImmutabilityRun</code></td><td><code>List.of()</code> is fully immutable; <code>add</code> throws</td></tr><tr><td><code>immutability/UnmodifiableListViewRun</code></td><td><code>Collections.unmodifiableList</code> is a read-only view; mutating the backing list affects the view</td></tr><tr><td><code>immutability/ArraysAsListTrapRun</code></td><td><code>Arrays.asList</code> is fixed-size: <code>set</code> works, <code>add</code> throws</td></tr><tr><td><code>performance/ArrayListVsLinkedListRandomAccessRun</code></td><td>O(1) vs O(n) random-access — <code>ArrayList</code> wins decisively</td></tr><tr><td><code>concurrent/CopyOnWriteSnapshotIteratorRun</code></td><td><code>CopyOnWriteArrayList</code> iterator sees a snapshot; modifications during iteration don&#39;t throw</td></tr><tr><td><code>concurrent/CopyOnWriteThreadSafetyRun</code></td><td><code>CopyOnWriteArrayList</code> survives concurrent readers + a writer with no external locking; <code>ArrayList</code> doesn&#39;t</td></tr></tbody></table><hr><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><ul><li><strong>A list that can grow with frequent random access by index?</strong> <code>ArrayList</code> — O(1) <code>get(i)</code>, fast append.</li><li><strong>An immutable list handed back from a factory?</strong> <code>List.of(...)</code> — fully read-only, rejects nulls.</li><li><strong>A read-only view over a mutable backing list?</strong> <code>Collections.unmodifiableList(...)</code> — the backing list can still mutate from outside, and the view will see those changes.</li><li><strong>A list shared across threads where reads vastly outnumber writes?</strong> <code>CopyOnWriteArrayList</code> — lock-free reads; every write copies the array.</li><li><strong>Array vs <code>ArrayList</code> for primitives?</strong> Array — no boxing. <code>ArrayList&lt;Integer&gt;</code> boxes every element.</li><li><strong>Why prefer <code>List&lt;T&gt;</code> over <code>String[]</code>?</strong> Arrays are covariant (<code>String[]</code> is an <code>Object[]</code>) → <code>ArrayStoreException</code> at runtime. Generics are invariant → compile-time safety.</li><li><strong>What&#39;s the <code>Arrays.asList</code> trap?</strong> Fixed-size but mutable — <code>set</code> works, <code>add</code>/<code>remove</code> throw <code>UnsupportedOperationException</code>.</li></ul><hr><h2 id="related-topics" tabindex="-1">Related topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related topics&quot;">​</a></h2><ul><li><strong>Maps</strong> and <strong>Sets</strong> — the other two collection families with their own trade-offs.</li><li><strong>Stream Collectors</strong> — covers how to produce list types from streams.</li><li><strong>Encapsulation</strong> — returning a mutable internal collection is a classic encapsulation violation; use <code>Collections.unmodifiableList(...)</code> or <code>List.copyOf(...)</code> to fix it.</li></ul>`,20)])])}const k=e(o,[["render",r]]);export{y as __pageData,k as default};
